source.exploreUrl:
@js: 
个人中心 = 1 

js = (cid, genre, gender) => `@js:
source.key + "/reading/bookapi/new_category/landing/v/?" + [
    "category_id=${cid}",
    "limit=50",
    "offset=" + (page - 1),
    "gender=${gender}",
    "genre=${genre}"
  ].join("&")`

readHistory = (path) => `@js:
let ck = "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : source.getLoginInfoMap()['手动登录Token'])
"{{source.key}}/multi-detail?book_id=" + getBookId(java.ajax('https://reading.snssdk.com/reading/bookapi/read_history/list/v/?aid=1967&version_code=99999,{"headers":{"Cookie":"install_id=2531502907244067;' + ck + '"}}'), page-1)`


obj = (title, url, type, type1) => ({
  title: title,
  url: url,
  style: {
    layout_flexGrow: 1,
    layout_flexBasisPercent: type
  }
})

arr = []
java.longToast("请稍等，发现列表正在热更新！")
index=[0, 1, 2]
for (let i of index) {
  // java.toast(i)
  let type = i
  $ = JSON.parse(java.ajax(source.key + "/reading/bookapi/new_category/front/v/?" + [
      "update_version_code=99999",
      "distinct_style=1",
      "new_category_tab=" + i
    ].join("&")
  )).data.category_tab_data
  cate = []
  cate.push(obj(
    "====== " + $.tab_name + " ======", "", 1
  ))
  $.cell_data.forEach((c) => {
    gender_1 = (type == 0 || type == 1) ? type : 1;
    genre_1 = type == 3 ? 1 : type == 5 ? 110 : type == 6 ? 130 : 0;
    cate.push(obj(
      c.cell_name,
      js(c.atom_data[0].category_data.category_id, genre_1, gender_1),
      1
    ))
    for (j = 2; j < 5; j++) {
      c.atom_data.slice(1).forEach((a) => {
        d = a.category_data
        if (d.name.length == j) {
          cate.push(obj(d.name, js(d.category_id, genre_1, gender_1), -1))
        }
      })
    }
  })
  arr = cate.concat(arr)
}

let book_shelf_url = 'https://fanqienovel.com/reading/bookapi/bookshelf/info/v:version/?aid=1967&iid=0&version_code=99999&update_version_code=57700'
let book_shelf_info = JSON.parse(java.ajax(book_shelf_url + ', ' + JSON.stringify({
  headers: {
    'Cookie': "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : (source.getLoginInfoMap() ? source.getLoginInfoMap() : {})['手动登录Token']),
  }
})))

java.log(JSON.stringify(book_shelf_info))

let username
if (book_shelf_info.code != 0) {
  个人中心 = 0
  // source.setVariable('{}')
} else {
  let uinfo = java.ajax("https://fanqienovel.com/api/user/info/v2," + JSON.stringify({ headers: { Cookie: "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : (source.getLoginInfoMap() ? source.getLoginInfoMap() : {})['手动登录Token']) }}))
  let arrB = []
  for (let i of book_shelf_info.data.book_shelf_info) {
    arrB.push(i.book_id)
  }
  uinfo = JSON.parse(uinfo)
  write_config('bookshelf.' + uinfo.data.id, arrB)
  write_config('userinfo', { name: uinfo.data.name, userid: uinfo.data.id })
  username = uinfo.data.name
}

let gro = []
push = (title, url, type) => gro.push({
  title: title,
  url: url,
  style: {
    layout_flexGrow: 1,
    layout_flexBasisPercent: type
  }
});

let sArr = []

if (个人中心) {
  let groups_bookids = {
    "组外": []
  }
  book_shelf_info.data.book_shelf_info.forEach(i => {
    if (!groups_bookids[i.group_name ? i.group_name : "组外"]) groups_bookids[i.group_name] = []
    groups_bookids[i.group_name ? i.group_name : "组外"].push(i.book_id)
  })

  Object.keys(groups_bookids).forEach(k => {
    var multi_detail_post_body = {
      data: {
        book_shelf_info: []
      }
    }
    groups_bookids[k].forEach(i => multi_detail_post_body.data.book_shelf_info.push({ book_id: String(i), item_id: '0' }))
    // var multi_detail_group_url = `https://fanqienovel.com/api/bookshelf/multidetail,${JSON.stringify(multi_detail_post_body)}`
    // var book_ids = getBookId(JSON.stringify(multi_detail_post_body)).join(",")
    push(k, "https://fanqienovel.com/fqbookshelf/groupName/" + k, 0.4)
  })
  if (Object.keys(groups_bookids).length % 2 != 0) push("占位", "", 0.4)
  // java.log(JSON.stringify(gro, null, 2))
  sArr.push(obj(username, '', 1))
  sArr.push(obj("🍅书架🍅", "https://fanqienovel.com/fqbookshelf", 1))
  sArr = sArr.concat(gro)
  // java.toast(JSON.stringify(sArr)) 
  sArr.push(obj("📔阅读历史📔", readHistory(), 1))
   //sArr.push(obj('首页推荐', "https://fanqienovel.com/tab/0", 0.4))
   sArr.push(obj('📚个性推荐📚', "https://api5-normal-lf.fqnovel.com/reading/bookapi/bookmall/cell/change/v1/?aid=1967&change_type=1&iid=1&app_name=novelapp&version_code=99999&cell_id=7012498777642631182&algo_type=101&category_id=0", 0.4))
   sArr.push(obj('🔝巅峰榜单🔝', "https://fanqienovel.com/api/author/misc/top_book_list/v1/?limit=50&offset=0&version_code=99999", 0.4))
   sArr.push(obj('👥男频热搜👥', "https://novel.snssdk.com/api/novel/channel/homepage/rank/rank_list/v2/?aid=13&app_name=news_article&app_version=9.7.3&channel=tengxun_tt&device_platform=android&os=android&device_type=ProjectTitan&os_api=29&os_version=10&openlive_plugin_status=1&isTTWebViewHeifSupport=0&limit=20&offset={{(page-1)*100}}&side_type=12&type=1", 0.4))
   sArr.push(obj('👍男频推荐👍', "https://novel.snssdk.com/api/novel/channel/homepage/rank/rank_list/v2/?aid=13&app_name=news_article&app_version=9.7.3&channel=tengxun_tt&device_platform=android&os=android&device_type=ProjectTitan&os_api=29&os_version=10&openlive_plugin_status=1&isTTWebViewHeifSupport=0&limit=20&offset={{(page-1)*100}}&side_type=10&type=1", 0.4))



}

arr = sArr.concat(arr)
JSON.stringify(arr)

source.jsLib:
function splitArray(input, size) {
  const output = []
  for (let i = 0; i < input.length; i += size) {
    output.push(input.slice(i, i + size))
  }
  return output
}
function write_config(key, value) {
  if (Packages.android.text.TextUtils.isEmpty(this.source.getVariable())) {
    this.source.setVariable('{}')
  }
  // this.java.log('var:' + this.source.getVariable())
  let obj = JSON.parse(this.source.getVariable())
  let arr = key.split('.')
  let temp = obj

  for (let i = 0; i < arr.length - 1; i++) {
    let currentKey = arr[i]
    if (!temp[currentKey]) {
      temp[currentKey] = {}
    }
    temp = temp[currentKey]
  }
  temp[arr[arr.length - 1]] = value
  this.source.setVariable(JSON.stringify(obj))
}
function read_config(key) {
  if (Packages.android.text.TextUtils.isEmpty(this.source.getVariable())) {
    this.source.setVariable('{}')
  }
  // this.java.log('var:' + this.source.getVariable())
  let obj = JSON.parse(this.source.getVariable())
  let arr = key.split('.')
  let res = JSON.parse(JSON.stringify(obj))
  for (let i = 0; i < arr.length; i++) {
    res = res[arr[i]] || (i < (arr.length - 1) ? {} : undefined)
    // this.java.log(JSON.stringify(res))
  }
  return res
}
function getBookId(url, page) {
  const {java} = this
  let $ = JSON.parse(url).data
  let list
  let arr
  if ($.book_shelf_info != 0 && $.book_shelf_info != undefined) {
   arr = $.book_shelf_info.map($ => $.book_id)
  } else if (let (list = $.data_list) list != 0 && $.data_list != undefined)  {
    arr = $.data_list.map($ => $.book_id_str)
  } else {
    java.toast("获取 book_id 失败，你可能需要登录！")
  }
  return arr.slice(page*100, (page+1)*100)
}

